<template><div ref="rail" class="clip-range"><div class="clip-selection" :style="{left:startPercent+'%',width:(endPercent-startPercent)+'%'}"/><button v-for="edge in edges" :key="edge" class="clip-handle" type="button" :disabled="disabled" :title="disabled?'片段导出中，请稍候':'拖动或使用方向键调整片段边界'" :style="{left:(edge==='start'?startPercent:endPercent)+'%'}" role="slider" aria-orientation="horizontal" :aria-label="edge==='start'?'片段开始位置':'片段结束位置'" :aria-valuemin="edge==='start'?0:start+minimum" :aria-valuemax="edge==='start'?end-minimum:duration" :aria-valuenow="edge==='start'?start:end" :aria-valuetext="secondsLabel(edge==='start'?start:end)" @pointerdown="begin($event,edge)" @pointermove="move" @pointerup="finish" @pointercancel="finish" @lostpointercapture="finish" @keydown="key($event,edge)"><i/><i/></button></div></template>
<script setup lang="ts">
import{computed,ref}from'vue';import{secondsLabel}from'@/lib/product-format';const props=defineProps<{duration:number;start:number;end:number;disabled?:boolean}>();const emit=defineEmits<{change:[range:{start:number;end:number}]}>();const rail=ref<HTMLElement|null>(null),edges=['start','end'] as const;let dragging:'start'|'end'|null=null,pointer=-1;const minimum=computed(()=>Math.min(.1,props.duration));const startPercent=computed(()=>props.duration?props.start/props.duration*100:0);const endPercent=computed(()=>props.duration?props.end/props.duration*100:100);
function set(edge:'start'|'end',value:number){if(props.disabled||!Number.isFinite(value)||props.duration<=0)return;const next=Math.round(value*10)/10;if(edge==='start')emit('change',{start:Math.max(0,Math.min(props.end-minimum.value,next)),end:props.end});else emit('change',{start:props.start,end:Math.min(props.duration,Math.max(props.start+minimum.value,next))})}
function begin(e:PointerEvent,edge:'start'|'end'){if(props.disabled||e.button!==0)return;e.preventDefault();dragging=edge;pointer=e.pointerId;(e.currentTarget as HTMLElement).focus();(e.currentTarget as HTMLElement).setPointerCapture(pointer)}
function move(e:PointerEvent){if(props.disabled||!dragging||e.pointerId!==pointer||!rail.value)return;const box=rail.value.getBoundingClientRect();if(box.width<=0)return;set(dragging,(e.clientX-box.left)/box.width*props.duration)}
function finish(){dragging=null;pointer=-1}
function key(e:KeyboardEvent,edge:'start'|'end'){if(props.disabled)return;const current=edge==='start'?props.start:props.end;const step=e.shiftKey?5:1;if(e.key==='ArrowLeft'||e.key==='ArrowDown'){e.preventDefault();set(edge,current-step)}else if(e.key==='ArrowRight'||e.key==='ArrowUp'){e.preventDefault();set(edge,current+step)}else if(e.key==='Home'){e.preventDefault();set(edge,0)}else if(e.key==='End'){e.preventDefault();set(edge,props.duration)}}
</script>
<style scoped>
.clip-range{position:absolute;inset:0;pointer-events:none}.clip-selection{position:absolute;top:0;bottom:0;border:2px solid #1673ff;background:#0a6dff0b;border-radius:8px;min-width:2px}.clip-handle{position:absolute;top:0;bottom:0;width:18px;transform:translateX(-50%);padding:0;border:0;background:transparent;pointer-events:auto;cursor:ew-resize;touch-action:none}.clip-handle i{position:absolute;left:0;width:18px;height:30px;border:1.5px solid #1673ff;border-radius:7px;background:#fff;box-shadow:0 1px 4px #216af51a}.clip-handle i:first-child{top:1px}.clip-handle i:last-child{bottom:1px}.clip-handle i:after{content:'';position:absolute;left:6px;top:8px;width:3px;height:11px;border-left:1px solid #1673ff;border-right:1px solid #1673ff}.clip-handle:hover i,.clip-handle:focus-visible i{background:#eaf3ff}.clip-handle:focus-visible{outline:2px solid #1673ff;outline-offset:4px;border-radius:7px}
</style>
